    original=retained(interpolation=interpolation)
    from . import curved_compound_exterior_nodes
    alternate=curved_compound_exterior_nodes.build(interpolation=interpolation)
    g=c.Graph(name)
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET':g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput');calls=[]
    for title,group in (('Retain accepted original corners',original),('Bounded exterior fallback',alternate)):
        call=g.node('GeometryNodeGroup',title);call.node_tree=group;calls.append(call)
        for socket in original.interface.items_tree:
            if socket.item_type=='SOCKET' and socket.in_out=='INPUT':g.bind(inp.outputs[socket.name],call.inputs[socket.name])
    use=c.choose(g,calls[0].outputs['Valid'],False,calls[1].outputs['Valid'],'BOOLEAN')
    for socket in original.interface.items_tree:
        if socket.item_type!='SOCKET' or socket.in_out!='OUTPUT':continue
        value=c.choose(g,use,calls[1].outputs[socket.name],calls[0].outputs[socket.name],
            'GEOMETRY' if socket.socket_type=='NodeSocketGeometry' else 'BOOLEAN')
        if socket.name=='Diagnostics':value=c._store(g,value,'exterior_fallback_used',use,'BOOLEAN')
        g.bind(value,out.inputs[socket.name])
    return g.g


